if(location.protocol==='file:'){const fonts={"light":"data:font/woff;base64,","regular":"data:font/woff;base64,","medium":"data:font/woff;base64,","bold":"data:font/woff;base64,"};const style=document.createElement('style');style.textContent=Object.entries(fonts).map(([name,url])=>'@font-face{font-family:CyberHarmony;font-style:normal;font-display:swap;font-weight:'+({light:300,regular:400,medium:500,bold:700}[name])+';src:url("'+url+'") format("woff");}').join('')+'@font-face{font-family:Harmony;font-weight:400;font-display:swap;src:url("'+fonts.regular+'") format("woff");}';document.head.appendChild(style);}